PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS customer (
    customer_id TEXT PRIMARY KEY,
    full_name TEXT NOT NULL,
    date_of_birth TEXT NOT NULL,
    email TEXT NOT NULL UNIQUE,
    phone TEXT NOT NULL,
    jurisdiction_profile TEXT NOT NULL CHECK (jurisdiction_profile IN ('POLICY_A','POLICY_B','POLICY_C')),
    credit_score INTEGER NOT NULL CHECK (credit_score BETWEEN 300 AND 900),
    risk_category TEXT NOT NULL CHECK (risk_category IN ('LOW','MEDIUM','HIGH')),
    customer_since TEXT NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS account (
    account_id TEXT PRIMARY KEY,
    customer_id TEXT NOT NULL,
    account_type TEXT NOT NULL CHECK (account_type IN ('SALARY_LINKED','SAVINGS_LINKED','CURRENT_LINKED')),
    repayment_method TEXT NOT NULL CHECK (repayment_method IN ('AUTO_DEBIT','MANUAL_TRANSFER')),
    account_status TEXT NOT NULL CHECK (account_status IN ('ACTIVE','SUSPENDED','CLOSED')),
    opened_date TEXT NOT NULL,
    closed_date TEXT,
    currency TEXT NOT NULL CHECK (currency IN ('INR')),
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    FOREIGN KEY (customer_id) REFERENCES customer(customer_id),
    CHECK (closed_date IS NULL OR closed_date >= opened_date),
    CHECK (((account_status = 'CLOSED') = (closed_date IS NOT NULL)))
);
CREATE INDEX IF NOT EXISTS idx_account_customer_id ON account(customer_id);

CREATE TABLE IF NOT EXISTS loan (
    loan_id TEXT PRIMARY KEY,
    account_id TEXT NOT NULL,
    customer_id TEXT NOT NULL,
    product_type TEXT NOT NULL CHECK (product_type IN ('PERSONAL_LOAN','CONSUMER_DURABLE','SMALL_BUSINESS','EDUCATION')),
    principal_amount REAL NOT NULL CHECK (principal_amount > 0),
    interest_rate_pct REAL NOT NULL CHECK (interest_rate_pct >= 0),
    tenor_installments INTEGER NOT NULL CHECK (tenor_installments >= 1),
    total_payable REAL NOT NULL,
    origination_date TEXT NOT NULL,
    first_due_date TEXT NOT NULL,
    maturity_date TEXT NOT NULL,
    loan_status TEXT NOT NULL CHECK (loan_status IN ('CURRENT','DELINQUENT','DEFAULT','PAID_OFF')),
    status_as_of TEXT NOT NULL,
    payoff_date TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    FOREIGN KEY (account_id) REFERENCES account(account_id),
    FOREIGN KEY (customer_id) REFERENCES customer(customer_id),
    CHECK (((loan_status = 'PAID_OFF') = (payoff_date IS NOT NULL))),
    CHECK (maturity_date >= first_due_date),
    CHECK (first_due_date > origination_date)
);
CREATE INDEX IF NOT EXISTS idx_loan_account_id ON loan(account_id);
CREATE INDEX IF NOT EXISTS idx_loan_customer_id ON loan(customer_id);
CREATE INDEX IF NOT EXISTS idx_loan_loan_status ON loan(loan_status);
CREATE INDEX IF NOT EXISTS idx_loan_origination_date ON loan(origination_date);

CREATE TABLE IF NOT EXISTS installment (
    installment_id TEXT PRIMARY KEY,
    loan_id TEXT NOT NULL,
    installment_number INTEGER NOT NULL CHECK (installment_number >= 1),
    due_date TEXT NOT NULL,
    amount_due REAL NOT NULL CHECK (amount_due > 0),
    principal_component REAL NOT NULL CHECK (principal_component >= 0),
    interest_component REAL NOT NULL CHECK (interest_component >= 0),
    amount_paid REAL NOT NULL,
    installment_status TEXT NOT NULL CHECK (installment_status IN ('NOT_DUE','PAID','PARTIALLY_PAID','OVERDUE')),
    fully_paid_date TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    FOREIGN KEY (loan_id) REFERENCES loan(loan_id),
    UNIQUE (loan_id, installment_number),
    CHECK (amount_paid >= 0 AND amount_paid <= amount_due + 0.005),
    CHECK (((installment_status = 'PAID') = (fully_paid_date IS NOT NULL)))
);
CREATE INDEX IF NOT EXISTS idx_installment_loan_id ON installment(loan_id);
CREATE INDEX IF NOT EXISTS idx_installment_due_date ON installment(due_date);
CREATE INDEX IF NOT EXISTS idx_installment_installment_status ON installment(installment_status);

CREATE TABLE IF NOT EXISTS payment (
    payment_id TEXT PRIMARY KEY,
