);
CREATE INDEX IF NOT EXISTS idx_payment_loan_id ON payment(loan_id);
CREATE INDEX IF NOT EXISTS idx_payment_customer_id ON payment(customer_id);
CREATE INDEX IF NOT EXISTS idx_payment_payment_date ON payment(payment_date);
