CREATE TABLE IF NOT EXISTS delinquency_snapshot (
    snapshot_id TEXT PRIMARY KEY,
    loan_id TEXT NOT NULL,
    snapshot_date TEXT NOT NULL,
    total_amount_paid REAL NOT NULL,
    outstanding_balance REAL NOT NULL,
    total_arrears REAL NOT NULL,
    overdue_installments INTEGER NOT NULL,
    days_past_due INTEGER NOT NULL,
    delinquency_bucket TEXT NOT NULL CHECK (delinquency_bucket IN ('PAID_OFF','CURRENT','DPD_1_30','DPD_31_60','DPD_61_90','DPD_90_PLUS')),
    loan_status TEXT NOT NULL CHECK (loan_status IN ('CURRENT','DELINQUENT','DEFAULT','PAID_OFF')),
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    FOREIGN KEY (loan_id) REFERENCES loan(loan_id),
    UNIQUE (loan_id, snapshot_date),
    CHECK (total_arrears >= 0),
    CHECK (outstanding_balance >= -0.005),
    CHECK (days_past_due >= 0)
);
CREATE INDEX IF NOT EXISTS idx_delinquency_snapshot_loan_id ON delinquency_snapshot(loan_id);
CREATE INDEX IF NOT EXISTS idx_delinquency_snapshot_snapshot_date ON delinquency_snapshot(snapshot_date);
CREATE INDEX IF NOT EXISTS idx_delinquency_snapshot_delinquency_bucket ON delinquency_snapshot(delinquency_bucket);

CREATE TABLE IF NOT EXISTS contact_preference (
