CREATE TABLE IF NOT EXISTS run_log (
    run_id TEXT PRIMARY KEY,
    run_type TEXT NOT NULL CHECK (run_type IN ('PRIORITIZATION','EXCEPTION_DETECTION','VALIDATION','RECONCILIATION','DATA_LOAD')),
    as_of_date TEXT NOT NULL,
    started_at TEXT NOT NULL,
    rules_version TEXT,
    summary TEXT
);
CREATE INDEX IF NOT EXISTS idx_run_log_run_type ON run_log(run_type);

CREATE TABLE IF NOT EXISTS prioritization_result (
    result_id TEXT PRIMARY KEY,
    run_id TEXT NOT NULL,
    case_id TEXT NOT NULL,
    as_of_date TEXT NOT NULL,
    priority_score REAL NOT NULL CHECK (priority_score BETWEEN 0 AND 100),
    priority_category TEXT NOT NULL CHECK (priority_category IN ('P1_HIGH','P2_MEDIUM','P3_LOW','HARDSHIP_REVIEW','MONITOR_PROMISE','SUPPRESSED')),
    contributing_factors TEXT NOT NULL,
    reason_codes TEXT NOT NULL,
    suppression_reasons TEXT,
