    recommended_channel TEXT CHECK (recommended_channel IS NULL OR recommended_channel IN ('PHONE','SMS','EMAIL','POST')),
    recommended_slot TEXT,
    explanation TEXT NOT NULL,
    FOREIGN KEY (run_id) REFERENCES run_log(run_id),
    FOREIGN KEY (case_id) REFERENCES collection_case(case_id),
    UNIQUE (run_id, case_id)
);
CREATE INDEX IF NOT EXISTS idx_prioritization_result_run_id ON prioritization_result(run_id);
CREATE INDEX IF NOT EXISTS idx_prioritization_result_case_id ON prioritization_result(case_id);
CREATE INDEX IF NOT EXISTS idx_prioritization_result_priority_category ON prioritization_result(priority_category);

