CREATE INDEX IF NOT EXISTS idx_exception_record_run_id ON exception_record(run_id);
CREATE INDEX IF NOT EXISTS idx_exception_record_exception_type ON exception_record(exception_type);
CREATE INDEX IF NOT EXISTS idx_exception_record_entity_id ON exception_record(entity_id);
